public interface Sortable {

    void sort(int[] data);
    String getName();
}

// Realization 1 — QuickSort keeps the promise its own way

public class QuickSort implements Sortable {
    @Override
    public void sort(int[] data) {
        // quicksort implementation
        System.out.println("Sorting with QuickSort");
    }

    @Override
    public String getName() { return "Quick Sort"; }
}

// Realization 2 — MergeSort keeps the same promise differently

public class MergeSort implements Sortable {
    @Override
    public void sort(int[] data) {
        // mergesort implementation
        System.out.println("Sorting with MergeSort");
    }

    @Override
    public String getName() { return "Merge Sort"; }
}

// Caller only knows the interface — works with any realization

public void sortData(Sortable sorter, int[] data) {
    System.out.println("Using: " + sorter.getName());
    sorter.sort(data);
}

// Both realizations are interchangeable here

sortData(new QuickSort(), data);   // works
sortData(new MergeSort(), data);   // works exactly the same way

