#include <iostream>
#include <vector>
#include <string>
using namespace std;

// The contract
class Sortable {
public:
    virtual void sort(vector<int>& data) = 0;
    virtual string getName() = 0;
    virtual ~Sortable() {}
};

// Realization 1 — QuickSort keeps the promise its own way

class QuickSort : public Sortable {
public:
    void sort(vector<int>& data) override {
        // quicksort implementation
        cout << "Sorting with QuickSort" << endl;
    }

    string getName() override { return "Quick Sort"; }
};

// Realization 2 — MergeSort keeps the same promise differently

class MergeSort : public Sortable {
public:
    void sort(vector<int>& data) override {
        // mergesort implementation
        cout << "Sorting with MergeSort" << endl;
    }

    string getName() override { return "Merge Sort"; }
};

// Caller only knows the interface — works with any realization

void sortData(Sortable& sorter, vector<int>& data) {
    cout << "Using: " << sorter.getName() << endl;
    sorter.sort(data);
}

int main() {
    vector<int> data = {5, 3, 1, 4, 2};

    // Both realizations are interchangeable here
    QuickSort quickSort;
    MergeSort mergeSort;
    sortData(quickSort, data);   // works
    sortData(mergeSort, data);   // works exactly the same way
    return 0;
}

