#include <iostream>
#include <string>
using namespace std;

// Three separate contracts

class Saveable   { public: virtual void save() = 0; virtual ~Saveable() {} };
class Printable  { public: virtual void print() = 0; virtual ~Printable() {} };
class Exportable { public: virtual void exportData(string format) = 0; virtual ~Exportable() {} };

// One class realizing all three
class Report : public Saveable, public Printable, public Exportable {
public:
    void save() override {
        cout << "Saving report to DB..." << endl;
    }

    void print() override {
        cout << "Printing report..." << endl;
    }

    void exportData(string format) override {
        cout << "Exporting as " << format << endl;
    }
};

int main() {
    Report report;

    // Each interface type can be used independently
    Saveable&   s = report;  s.save();              // only save visible
    Printable&  p = report;  p.print();              // only print visible
    Exportable& e = report;  e.exportData("PDF");    // only export visible
    return 0;
}

