#include <string>
using namespace std;

// Abstract class — shared base for related shapes

class Shape {
protected:
    string colour;                      // shared state
public:
    virtual double area() = 0;           // must implement
    virtual double perimeter() = 0;      // must implement

    string describe() {                  // shared concrete method
        return colour + " shape with area " + to_string(area());
    }
    virtual ~Shape() {}
};

class Circle : public Shape {
private:
    double radius;
public:
    double area() override      { return M_PI * radius * radius; }
    double perimeter() override { return 2 * M_PI * radius; }
};

// Abstract class (interface) — capability across unrelated classes

class Resizable {
public:
    virtual void resize(double factor) = 0;
    virtual ~Resizable() {}
};

// Unrelated classes can both be Resizable

class Window    : public Resizable { public: void resize(double f) override { /* ... */ } };
class FontStyle : public Resizable { public: void resize(double f) override { /* ... */ } };

