#include <iostream>
#include <vector>
#include <memory>
using namespace std;

// Observer pattern — realization in action
class OrderEventListener {
public:
    virtual void onOrderPlaced(Order& order) = 0;
    virtual ~OrderEventListener() {}
};

// Three classes realize the same listener interface

class InventoryService : public OrderEventListener {
public:
    void onOrderPlaced(Order& order) override {
        cout << "Reserving stock for: " << order.getId() << endl;
    }
};

class EmailNotifier : public OrderEventListener {
public:
    void onOrderPlaced(Order& order) override {
        cout << "Sending confirmation for: " << order.getId() << endl;
    }
};

class AnalyticsTracker : public OrderEventListener {
public:
    void onOrderPlaced(Order& order) override {
        cout << "Recording revenue for: " << order.getId() << endl;
    }
};

int main() {
    // EventBus iterates all listeners — each is a realization of the same interface
    vector<unique_ptr<OrderEventListener>> listeners;
    listeners.push_back(make_unique<InventoryService>());
    listeners.push_back(make_unique<EmailNotifier>());
    listeners.push_back(make_unique<AnalyticsTracker>());

    for (auto& l : listeners) {
        l->onOrderPlaced(order);
    }
    return 0;
}

